// Context to store the latest values from UI elements
// Initialize with default values
let curveTyp = context.get('curveTyp') || "0"; 
let frequency = context.get('frequency') || 1000;
let amplitude = context.get('amplitude') || 1.0;
let offset = context.get('offset') || 1.65;
let dataMax = context.get('dataMax') || 2048;

// Update context if the message is from a UI element setting a value
if (msg.topic === 'curveTyp') {
    curveTyp = msg.payload;
    context.set('curveTyp', curveTyp);
}
if (msg.topic === 'frequency') {
    frequency = parseFloat(msg.payload); // Ensure number
    context.set('frequency', frequency);
}
if (msg.topic === 'amplitude') {
    amplitude = parseFloat(msg.payload); // Ensure number
    context.set('amplitude', amplitude);
}
if (msg.topic === 'offset') {
    offset = parseFloat(msg.payload); // Ensure number
    context.set('offset', offset);
}
if (msg.topic === 'dataMax') {
    dataMax = parseInt(msg.payload); // Ensure integer
    context.set('dataMax', dataMax);
}

// If triggered by the button, create the payload for the genCmdAWG function
if (msg.topic === 'trigger') {
    msg.payload = {
        curveTyp: parseInt(curveTyp), // Convert to number for the main function
        frequency: frequency,
        amplitude: amplitude,
        offset: offset,
        dataMax: dataMax
    };
    return msg; // Pass the collected data to the next node
}

// For other messages (UI inputs updating context), don't pass them on yet
return null;

