function decToHex(d, padding) {
    var hex = Number(d).toString(16).toUpperCase();
    padding = typeof (padding) === "undefined" || padding === null ? padding = 2 : padding;
    while (hex.length < padding) {
        hex = "0" + hex;
    }
    return hex;
}

function isPrime(num) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 === 0 || num % 3 === 0) return false;
    for (let i = 5; i * i <= num; i = i + 6) {
        if (num % i === 0 || num % (i + 2) === 0) return false;
    }
    return true;
}

function nearestPrime(num) {
    num = Math.round(num);
    if (num <= 2) return 2;
    if (num % 2 === 0) num++; // Start with an odd number
    while (true) {
        if (isPrime(num)) return num;
        num += 2; 
    }
}

// --- Main Function Logic (adapted from genCmdAWG) ---

let curveTyp = msg.payload.curveTyp; 
let frequency = parseFloat(msg.payload.frequency);
let amp = parseFloat(msg.payload.amplitude);
let off = parseFloat(msg.payload.offset);
let dataMax = msg.payload.dataMax ? parseInt(msg.payload.dataMax) : 2048; 


var cmd = "";
var maxV = 3.3;
var maxC; 
var fCalc; 
var nSample; 

var start;  
var stop;
var step;
var repeat;
var ampC;
var offC;
var infoX =""; 

var boardX = 2; // Hardcoded for Arduino MKR WIFI 1010

if (boardX == 2) { // Arduino MKR WIFI 1010
    nSample = 78000 * 5; 
    maxC = 4095;         // 12-bit DAC
    fCalc = 1E8 / 6;     
} else {
    node.error("Unsupported board type configuration!", msg);
    return null; 
}

if (isNaN(curveTyp) || isNaN(frequency) || isNaN(amp) || isNaN(off)) {
    node.error("Invalid input: One or more parameters are not numbers.", msg);
    msg.payload = "Error: Invalid input parameters.";
    // Optionally send to a UI text node for error display
    // node.send([null, msg]); // Assuming a second output for errors
    return null; 
}


if (curveTyp == 0) {  // DC
    cmd = "T";         
    start = Math.trunc(maxC / maxV * off);
    if (start < 0) start = 0;
    if (start > maxC) start = maxC;

    cmd = cmd + 	decToHex(start,4);
    cmd = cmd + 	decToHex(start,4);  
    cmd = cmd + 	"0000";       // step = 0
    cmd = cmd +     decToHex(512,8);  // repeat 

    stop = start; step = 0; repeat = 512; 
    infoX = `DC Mode: Value=${off}V -> Code=${start}`;

} else if (curveTyp == 1) {  // Sine
    cmd = "S"; 
    let internalMaxC = (Math.pow(2,30)-1); 

    ampC = Math.trunc( internalMaxC / maxV * amp);
    offC = Math.trunc( internalMaxC / maxV * off);

    if (offC >= internalMaxC) { offC = internalMaxC; }
    if (offC < 0) { offC = 0;}

    if ((offC + ampC) >= internalMaxC) { ampC = internalMaxC - offC; } 
    if (ampC < 0) { ampC = 0; }
    if ((offC - ampC) < 0) { ampC = offC; }

    let timeBaseForSine = 1; 
    var timeX = (timeBaseForSine + 1) / 4; 

    var nCycle = Math.round(dataMax / fCalc * timeX * nSample * frequency);
    if (nCycle <= 0 && frequency > 0) nCycle = 1; 
    else if (frequency === 0) nCycle = 0; // No cycles for DC

    if (nCycle > 0 && (nCycle % 2) == 0) { nCycle = nCycle + 1; } 

    var correctedFrequency = frequency;
    if (frequency > 0 && nCycle > 0) {
      correctedFrequency = nearestPrime(nCycle) * fCalc / dataMax / timeX / nSample;
    } else {
      correctedFrequency = 0; // No frequency correction if input frequency is 0
    }

    if (correctedFrequency > 0) {
        step = Math.trunc(Math.pow(2,23) / fCalc * nSample * correctedFrequency); // 2^23 = 1024*1024*8
    } else {
        step = 0; // No frequency, so step is 0
    }

    if (step < 0) step = 0;
    if (step > 0xFFFFFFFF) step = 0xFFFFFFFF; // Max 32-bit value

    cmd = cmd + 	decToHex(step,8);   // step (32-bit)
    cmd = cmd + 	decToHex(ampC,8);   // amplitude (32-bit)
    cmd = cmd + 	decToHex(offC,8);  // offset (32-bit)

    start = offC - ampC; 
    stop = offC + ampC;  
    repeat = 0; 

    infoX = `Sine: Freq=${frequency.toPrecision(4)}Hz (map to ${correctedFrequency.toPrecision(4)}Hz), Amp=${amp}V, Off=${off}V. nCycle: ${nCycle}`;
    msg.payload_correctedFrequency = correctedFrequency; // For display

} else if (curveTyp == 2 || curveTyp == 3 || curveTyp == 4) {  // Pulse, Triangle, Stair (all use 'T' command)
    cmd = "T";
    start = Math.trunc(maxC / maxV * (off-amp));
    stop = Math.trunc(maxC / maxV * (off+amp));

    if (start < 0) start = 0;
    if (start > maxC) start = maxC;
    if (stop < 0) stop = 0;
    if (stop > maxC) stop = maxC;


    if (start > stop) { 
        let tempVal = start;
        start = stop;
        stop = tempVal;
        node.warn("Amplitude and offset resulted in start > stop. Swapped.");
    }

    let delta = stop - start;

    if (frequency === 0) { // Static output if frequency is 0
        step = 0; // No change over time
        repeat = 0xFFFFFFFF; 

    } else if (delta === 0) { // If start and stop are the same (e.g. amp=0 for pulse/triangle)
        step = 0; // No change needed if already at target
        repeat = Math.trunc(1 / frequency / 2 * fCalc); // Standard repeat for this frequency
        if (repeat < 1) repeat = 1;
    } else {
        if (curveTyp == 2) { // Pulse (Triangle Generator based)
            step = delta; // Full swing in one step duration for sharp edges (conceptually)
            repeat = Math.trunc(1 / frequency / 2 * fCalc);
            infoX = `Pulse: Freq=${frequency}Hz, Low=${(off-amp).toPrecision(3)}V, High=${(off+amp).toPrecision(3)}V`;
        } else if (curveTyp == 3) { // Triangle
            var repMax = 64; // From original JS
            let rawRepeat = 1 / frequency / delta / 2 * fCalc;
            if (rawRepeat >= repMax) { 
                repeat = Math.trunc(rawRepeat); 
                step = 1;
            } else {    
                if (rawRepeat < 1) rawRepeat = 1; 
                step = Math.trunc(repMax / rawRepeat);
                if (step === 0 && delta > 0) step = 1; // Ensure step is at least 1 if there's a range
                stop = start + Math.trunc(delta / step) * step; // Adjust stop to be multiple of step
                repeat = repMax;
            }   
            infoX = `Triangle: Freq=${frequency}Hz, Low=${(off-amp).toPrecision(3)}V, High=${(off+amp).toPrecision(3)}V`;
        } else if (curveTyp == 4) { // Stair
            let numStairs = 5;
            repeat = Math.trunc(1 / frequency / 2 * fCalc / numStairs);
            step = Math.trunc(delta / numStairs);
            if (step == 0 && delta > 0) step = 1;
            stop = start + numStairs * step; // Ensure stop is consistent with steps
            if (stop > maxC) { // If adjusted stop exceeds maxC, recalculate based on maxC
                stop = maxC;
                delta = stop - start;
                step = Math.trunc(delta / numStairs);
                if (step == 0 && delta > 0) step = 1;
                stop = start + numStairs * step; 
            }
            infoX = `Stair (${numStairs} steps): Freq=${frequency}Hz, Low=${(off-amp).toPrecision(3)}V, High=${(off+amp).toPrecision(3)}V`;
        }
        if (repeat < 1 && frequency > 0) repeat = 1;
    }

    if (step < 0) step = 0;
    if (step > 0xFFFF) step = 0xFFFF; // Max 16-bit for T command step
    if (repeat > 0xFFFFFFFF) repeat = 0xFFFFFFFF; // Max 32-bit for T command repeat

    cmd = cmd + 	decToHex(start,4);
    cmd = cmd + 	decToHex(stop,4);  
    cmd = cmd + 	decToHex(step,4);     
    cmd = cmd +     decToHex(repeat,8);  
} else {
    node.error("Unknown curveTyp: " + curveTyp, msg);
    return null; 
}

// Output the command string for the serial node
msg.payload = cmd;

// Add other info for debugging or display
let debugParams = {
    curveType: curveTyp,
    inputFrequency: frequency,
    amplitude: amp,
    offset: off,
    dataMax: dataMax,
    calc_start_code: start,
    calc_stop_code: stop,
    calc_step_code: step,
    calc_repeat_val: repeat,
    board_max_dac_code: maxC,
    board_fCalc_hz: fCalc.toExponential(2)
};
if (curveTyp == 1 && msg.payload_correctedFrequency !== undefined) {
    debugParams.corrected_sine_freq_hz = msg.payload_correctedFrequency.toPrecision(4);
}

msg.debugInfo = {
    commandString: cmd,
    description: infoX,
    parameters: debugParams
};

// For displaying info on the UI
msg.displayInfo = `${infoX}\nCommand: ${cmd}`;

return msg;
